/**
 * Calculates the nth number in the Fibonacci sequence.
 * 
 * @param {number} n The position of the number in the Fibonacci sequence.
 * @returns {number} The nth number in the Fibonacci sequence.
 * @throws {Error} If n is not a non-negative integer.
 */
function fibonacci(n) {
    // Base case: If n is less than or equal to 1, return n immediately.
    if (n <= 1) return n;

    // Recursive case: Calculate the nth number as the sum of the two preceding numbers.
    // This is where the magic of the Fibonacci sequence happens!
    return fibonacci(n - 1) + fibonacci(n - 2);
}
